using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup and register the service
var trainingService = new ModelTrainingService();
trainingService.TrainAndEvaluate();
builder.Services.AddSingleton(trainingService);

// Register the pooled prediction engine (thread-safe)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainingService.ModelPath);

var app = builder.Build();

app.MapPost("/api/tickets/classify", (
    TicketRequest request,
    PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
    ModelTrainingService training) =>
{
    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority
    };

    var prediction = predictionPool.Predict(input);

    var labels = new[] { "Billing", "General", "Technical" };
    var confidence = new Dictionary<string, float>();
    for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
    {
        confidence[labels[i]] = prediction.Score[i];
    }

    return Results.Ok(new PredictionResponse
    {
        PredictedCategory = prediction.Category,
        Confidence = confidence
    });
});

app.MapGet("/api/tickets/metrics", (ModelTrainingService training) =>
{
    var metrics = training.Metrics;
    return metrics is null
        ? Results.NotFound("Model has not been trained yet.")
        : Results.Ok(metrics);
});

app.Run();

